const gpiod=require('../lib/index.js');

const gpio5=new gpiod('/dev/gpiochip6'); //for gpio5 the chardev is gpiochip6


console.log("OUTPUT");

gpio5.open()
.then(async ()=>{
    console.log("File got open");

    try{


        console.log("----mode request------");
        let req=await gpio5.request_mode(7,gpiod.OUTPUT_MODE); //gpio5_7 as output
       
        let state=false;
        setInterval(async ()=>{
            state=!state;
            await gpio5.set_values(req,state); //set value to the requested pin
        },400);

    }
    catch(err){
        console.error(err);
    }

})
.catch(err=>{
    console.error(err);
});
